/*
 * COMPOSITION: One full-bleed editorial plate (7x5.5 @ z=0) is the sole
 *   backdrop; kicker/hero(2 lines)/rule/body/caption sit left-aligned on a
 *   strict baseline grid just in front (z=0.01) with letterpress duplicate
 *   hero glyphs at z=-0.02 for print-depth. Text world-size is calibrated
 *   at runtime against ctx.fontAtlas output so glyphs never overflow the
 *   plate (root cause of the prior blown-out render).
 * LIGHT RIG: rig-dusk-editorial — warm directional key (2.8) + warm point
 *   fill (3) + cool directional rim (1.7) + 0.09 ambient floor, positions
 *   scaled to the plate's bounding radius, applied only to the lit backdrop
 *   plate + accent rule (text glyphs stay unlit/high-contrast paper ink).
 * MATERIAL STRATEGY: matte MeshStandardNodeMaterial plate (roughness 0.85,
 *   metalness 0) driven by a TSL vertical gradient + fine grain colorNode;
 *   signal-red underline rule is an emissive MeshStandardNodeMaterial slab
 *   (emissiveIntensity 1.2, capped under 2.3). Hero text is the single
 *   brightest read (full paper white); kicker/body/caption are muted greys
 *   graded below it to keep ONE brightest element.
 * MOTION: rise-in per text block (y+0.4->0, opacity 0->1, 700ms power-out,
 *   80ms stagger, top-to-bottom) then the accent rule draws scaleX 0->1
 *   over 500ms once the hero has landed; idle state has no perpetual motion.
 * FOCAL ELEMENT: the two-line hero headline "PRECISION IS / A HABIT." is the
 *   single brightest, largest element — everything else graded beneath it.
 */

import {
  MeshStandardNodeMaterial,
  DirectionalLight,
  PointLight,
  AmbientLight,
  PlaneGeometry,
  Group,
  Box3,
} from 'three/webgpu';
import { uv, mix, color, sin, fract } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'nova-editorial-headline';

  const colors = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, idx = 0) => items.filter((i) => i.role === role)[idx];

  const kicker = byRole('kicker', 0) ?? { text: 'NOVA ATELIER / JOURNAL' };
  const heroLine1 = byRole('hero', 0) ?? { text: 'PRECISION IS' };
  const heroLine2 = byRole('hero', 1) ?? { text: 'A HABIT.' };
  const body = byRole('body', 0) ?? { text: '' };
  const caption = byRole('caption', 0) ?? { text: '' };

  const disposables = { geometries: [], materials: [], textObjects: [] };
  const timelines = [];

  // ---------------------------------------------------------------------
  // CALIBRATION — measure real world-units-per-px of the glyph atlas so
  // text is sized against actual output, not an assumed conversion ratio.
  // This is what fixes the prior giant/blown-out hero glyphs defect.
  // ---------------------------------------------------------------------
  function calibrateUnitsPerPx() {
    const probe = ctx.fontAtlas.createText('Hg', { fontSize: 100, align: 'left' });
    probe.updateMatrixWorld?.(true);
    const box = new Box3().setFromObject(probe);
    const h = box.max.y - box.min.y;
    probe.traverse?.((c) => {
      c.geometry?.dispose?.();
      if (c.material) {
        if (Array.isArray(c.material)) c.material.forEach((m) => m.dispose());
        else c.material.dispose();
      }
    });
    return h > 0 ? h / 100 : 0.005;
  }

  const unitsPerPx = calibrateUnitsPerPx();
  const pxFor = (worldUnits) => worldUnits / unitsPerPx;

  // scene-unit em heights from the design token scale
  const EM = { kicker: 0.09, hero: 0.62, body: 0.13, caption: 0.09 };

  // ---------------------------------------------------------------------
  // BACKDROP PLATE — vertical engineered gradient + subtle grain (TSL)
  // ---------------------------------------------------------------------
  const plateGeo = new PlaneGeometry(7, 5.5);
  const plateMat = new MeshStandardNodeMaterial({ roughness: 0.85, metalness: 0.0 });

  const uvNode = uv();
  const gradient = mix(color(colors.background), color(colors.surface), uvNode.y);
  const hash = fract(
    sin(uvNode.x.mul(12.9898).add(uvNode.y.mul(78.233))).mul(43758.5453)
  );
  const grain = hash.sub(0.5).mul(0.015);
  plateMat.colorNode = gradient.add(grain);

  const plate = new THREE.Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);
  disposables.geometries.push(plateGeo);
  disposables.materials.push(plateMat);

  // ---------------------------------------------------------------------
  // LIGHT RIG — rig-dusk-editorial, subject-relative positions scaled
  // ---------------------------------------------------------------------
  const radius = 3.5;
  const ambient = new AmbientLight(0xffffff, 0.09);
  root.add(ambient);

  const key = new DirectionalLight(0xffc890, 2.8);
  key.position.set(3 * radius, 0.9 * radius, 1.2 * radius);
  key.target.position.set(0, 0.4, 0);
  root.add(key, key.target);

  const fill = new PointLight(0xb9a68e, 3, 9, 2);
  fill.position.set(-2.4 * radius, 0.6 * radius, 1.8 * radius);
  root.add(fill);

  const rim = new DirectionalLight(0xf2f4f6, 1.7);
  rim.position.set(-1.8 * radius, 2.8 * radius, -2 * radius);
  rim.target.position.set(0, 0.6, 0);
  root.add(rim, rim.target);

  // ---------------------------------------------------------------------
  // TYPE — strict baseline grid, left aligned at x=-3.1
  // Hero = brightest (paper white). Kicker/body/caption graded below it
  // with muted greys so there is exactly ONE brightest element.
  // ---------------------------------------------------------------------
  const X = -3.1;
  const MUTED_LABEL = '#aab0bb';
  const MUTED_BODY = '#c7cbd3';

  function makeText(str, opts, pos) {
    const obj = ctx.fontAtlas.createText(str, opts);
    obj.position.set(pos[0], pos[1], pos[2]);
    root.add(obj);
    disposables.textObjects.push(obj);
    return obj;
  }

  const kickerFontPx = pxFor(EM.kicker);
  const kickerObj = makeText(
    kicker.text,
    {
      fontSize: kickerFontPx,
      color: MUTED_LABEL,
      align: 'left',
      letterSpacingPx: 0.12 * kickerFontPx,
    },
    [X, 1.7, 0.01]
  );

  const heroFontPx = pxFor(EM.hero);
  const heroLetterSpacing = -0.015 * heroFontPx;

  // letterpress shadow duplicates for the hero lines (ink, 0.02 units behind)
  const heroShadow1 = makeText(
    heroLine1.text,
    { fontSize: heroFontPx, color: colors.ink, align: 'left', letterSpacingPx: heroLetterSpacing },
    [X, 0.9, -0.02]
  );
  const heroShadow2 = makeText(
    heroLine2.text,
    { fontSize: heroFontPx, color: colors.ink, align: 'left', letterSpacingPx: heroLetterSpacing },
    [X, 0.25, -0.02]
  );

  const heroObj1 = makeText(
    heroLine1.text,
    { fontSize: heroFontPx, color: colors.paper, align: 'left', letterSpacingPx: heroLetterSpacing },
    [X, 0.9, 0.01]
  );
  const heroObj2 = makeText(
    heroLine2.text,
    { fontSize: heroFontPx, color: colors.paper, align: 'left', letterSpacingPx: heroLetterSpacing },
    [X, 0.25, 0.01]
  );

  const bodyFontPx = pxFor(EM.body);
  const bodyObj = makeText(
    body.text,
    {
      fontSize: bodyFontPx,
      color: MUTED_BODY,
      align: 'left',
      maxWidthPx: pxFor(4.5),
      letterSpacingPx: 0,
    },
    [X, -0.8, 0.01]
  );

  const captionFontPx = pxFor(EM.caption);
  const captionObj = makeText(
    caption.text,
    {
      fontSize: captionFontPx,
      color: MUTED_LABEL,
      align: 'left',
      letterSpacingPx: 0.08 * captionFontPx,
    },
    [X, -1.9, 0.01]
  );

  // ---------------------------------------------------------------------
  // ACCENT UNDERLINE RULE — signal red, emissive, drawn after hero lands
  // ---------------------------------------------------------------------
  const ruleGeo = new PlaneGeometry(2.2, 0.05);
  const ruleMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(colors.accent),
    emissive: new THREE.Color(colors.accent),
    emissiveIntensity: 1.2
